fn resource_name<'a>(
    resource: &'a renderdocx::replay::ResourceInfo,
    renames: Option<&'a serde_json::Value>,
) -> &'a str {
    resource
        .rename_key
        .as_deref()
        .and_then(|key| renames.and_then(|doc| annotations::resource_name(doc, key).ok().flatten()))
        .unwrap_or(&resource.name)
}

fn descriptor_type_label(language: Language, value: Option<u64>) -> String {
    match value {
        Some(0) => language
            .text("Unknown", "未知")
            .to_owned(),
        Some(1) => language
            .text(
                "Constant buffer",
                "常量缓冲区",
            )
            .to_owned(),
        Some(2) => language
            .text("Sampler", "采样器")
            .to_owned(),
        Some(3) => language
            .text(
                "Image sampler",
                "图像采样器",
            )
            .to_owned(),
        Some(4) => language
            .text("Image", "图像")
            .to_owned(),
        Some(5) => language
            .text("Buffer", "缓冲区")
            .to_owned(),
        Some(6) => language
            .text(
                "Typed buffer",
                "类型化缓冲区",
            )
            .to_owned(),
        Some(7) => language
            .text(
                "Read/write image",
                "读写图像",
            )
            .to_owned(),
        Some(8) => language
            .text(
                "Read/write typed buffer",
                "读写类型化缓冲区",
            )
            .to_owned(),
        Some(9) => language
            .text(
                "Read/write buffer",
                "读写缓冲区",
            )
            .to_owned(),
        Some(10) => language
            .text(
                "Acceleration structure",
                "加速结构",
            )
            .to_owned(),
        Some(value) => format!(
            "{} ({value})",
            language.text("Unknown", "未知")
        ),
        None => language
            .text("Unavailable", "不可用")
            .to_owned(),
    }
}

fn descriptor_stage_label(value: Option<u64>) -> String {
    const STAGES: [&str; 14] = [
        "Vertex",
        "Hull / Tessellation control",
        "Domain / Tessellation evaluation",
        "Geometry",
        "Pixel / Fragment",
        "Compute",
        "Task / Amplification",
        "Mesh",
        "RayGen",
        "Intersection",
        "AnyHit",
        "ClosestHit",
        "Miss",
        "Callable",
    ];
    value
        .and_then(|value| {
            usize::try_from(value)
                .ok()
                .and_then(|index| STAGES.get(index))
                .copied()
        })
        .map(str::to_owned)
        .or_else(|| value.map(|value| format!("#{value}")))
        .unwrap_or_else(|| "—".into())
}

