    #[inline(never)]
    fn exercise_texture_preview_gestures(
        cx: &mut TestAppContext,
        view: &Entity<Workspace>,
        handle: gpui::WindowHandle<Root>,
    ) {
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            window.scroll(
                "capture-details-scroll",
                ScrollDelta::Pixels(point(px(0.), px(-800.))),
                cx,
            );
            reveal_details(window, "texture-preview-image", cx);
            assert!(window.find("texture-preview-image").visible());
            assert!(window.find("texture-preview-image").bounds().size.height > px(0.));
            window.click("texture-preview-image", cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update(|cx| {
            let state = view.read(cx);
            let pixel = state.pixel.as_ref().expect("preview click picks a pixel");
            assert_eq!((pixel.x, pixel.y, pixel.mip), (4, 4, 1));
            assert_eq!(state.preview_fitted_transform().unwrap().0, 22.5);
        });
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            reveal_details(window, "texture-preview-image", cx);
            window.scroll(
                "texture-preview-image",
                ScrollDelta::Lines(point(0., 1.)),
                cx,
            );
        })
        .unwrap();
        cx.run_until_parked();
        let zoomed_offset = cx.update(|cx| {
            let selection = view.read(cx).texture_selection;
            assert!(selection.preview_scale.is_some());
            selection.preview_offset
        });
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            reveal_details(window, "texture-preview-image", cx);
            let bounds = window.find("texture-preview-image").bounds();
            let from = bounds.origin + gpui::point(bounds.size.width / 2., bounds.size.height / 2.);
            let to = from + gpui::point(px(10.), px(5.));
            window.drag(from, to, cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update(|cx| {
            let offset = view.read(cx).texture_selection.preview_offset;
            assert!(
                offset[0] > zoomed_offset[0] && offset[1] > zoomed_offset[1],
                "before={zoomed_offset:?} after={offset:?} drag={:?}",
                view.read(cx).preview_drag
            );
            assert!(view.read(cx).preview.is_some());
        });
        cx.update_window(handle.into(), |_, window, cx| {
            window.render_frame(cx);
            reveal_details(window, "texture-view-fit", cx);
            window.click("texture-view-fit", cx);
            reveal_details(window, "texture-next-channel", cx);
            window.click("texture-next-channel", cx);
        })
        .unwrap();
    }

    fn reveal_details(window: &mut Window, id: &'static str, cx: &mut App) {
        for _ in 0..60 {
            window.render_frame(cx);
            let target = window.find(id);
            let viewport = window.find("capture-details-scroll").bounds();
            let bounds = target.bounds();
            if target.visible()
                && bounds.origin.y >= viewport.origin.y
                && bounds.origin.y + bounds.size.height <= viewport.origin.y + viewport.size.height
            {
                return;
            }
            let delta = if bounds.origin.y < viewport.origin.y {
                100.0
            } else {
                -100.0
            };
            window.dispatch_event(
                gpui::ScrollEvent {
                    position: point(
                        viewport.origin.x + viewport.size.width - px(4.),
                        viewport.origin.y + viewport.size.height / 2.,
                    ),
                    delta: ScrollDelta::Pixels(point(px(0.), px(delta))),
                    modifiers: window.modifiers(),
                    ..Default::default()
                }
                .to_platform_input(),
                cx,
            );
        }
        panic!("Could not reveal {id}");
    }

    #[test]
    fn timeline_zoom_and_pan_handle_the_full_event_id_range() {
        let mut view = TimelineView::default();
        view.model.max_event = u32::MAX;
        view.end = u32::MAX;
        view.zoom(true, Some(u32::MAX));
        assert_eq!(view.end, u32::MAX);
        assert_eq!(u64::from(view.end) - u64::from(view.start) + 1, 1u64 << 31);
        view.pan(false);
        assert!(view.end < u32::MAX);
        view.zoom(false, None);
        assert_eq!((view.start, view.end), (0, u32::MAX));
        for _ in 0..32 {
            view.zoom(true, Some(u32::MAX));
        }
        assert_eq!((view.start, view.end), (u32::MAX, u32::MAX));
        view.pan(false);
        assert_eq!(view.start, u32::MAX - 1);
    }

    #[test]
    fn timeline_wheel_zoom_anchors_and_pan_clamps() {
        let mut view = TimelineView::default();
        view.model.max_event = u32::MAX;
        view.end = u32::MAX;
        view.zoom_at(15.0, 0.25);
        let anchor = u64::from(view.start) + (u64::from(view.end) - u64::from(view.start) + 1) / 4;
        assert!((anchor as i64 - (1_i64 << 30)).abs() <= 1);
        let old = view.start;
        view.pan_pixels(-100.0, 768.0);
        assert!(view.start > old);
        view.pan_pixels(f32::MAX, 768.0);
        assert_eq!(view.start, 0);
        view.zoom_at(-200.0, 1.0);
        assert_eq!((view.start, view.end), (0, u32::MAX));
        view.start = 5;
        view.end = 6;
        view.zoom_at(1.0, 0.0);
        assert_eq!((view.start, view.end), (5, 5));
        view.start = 0;
        view.end = u32::MAX;
        view.zoom_at(f32::NAN, 0.5);
        view.pan_pixels(10.0, 0.0);
        assert_eq!((view.start, view.end), (0, u32::MAX));
    }

